INSERT INTO `sys_counts_task_item` VALUES ('01daa8147fd69727e92ce34740253f0f', '1', 'DS_INDEX_SS_COUNTS_TASK', '数据概况', 'datas', '0', '1', null, 'SELECT t.name,FORMAT(t.total,0) total,p.hysj,k.djsqy,gang as hybfb FROM \r\n(SELECT \'SSTJ\' `name`,count(1) `total` from `scientific_names_info` ) t\r\nLEFT JOIN (SELECT \'SSTJ\' `name`,count(DISTINCT kingdomc) `hysj` from `scientific_names_info`) p ON t.`name`=p.`name`\r\nLEFT JOIN (SELECT \'SSTJ\' `name`,count(DISTINCT men) `djsqy` from `scientific_names_info`) k ON t.`name`=k.`name`\r\nLEFT JOIN (SELECT \'SSTJ\' `name`,count(DISTINCT gang) `gang` from `scientific_names_info`) f ON t.`name`=f.`name`', null, null, null, 'admin', '2024-07-24 20:45:44', 'admin', '2024-07-24 15:05:18', '1');
INSERT INTO `sys_counts_task_item` VALUES ('112233547fd69727e92ce34740253f0f', '1', 'DS_INDEX_SSSJ_COUNTS_TASK', '时间分布', 'datas', '0', '1', null, 'SELECT scrutinydate `name`,count(1) value from `scientific_names_info` WHERE !ISNULL(scrutinydate) AND scrutinydate!=\'\' GROUP BY name ORDER BY name LIMIT 20', null, null, null, 'admin', '2024-07-24 20:45:44', 'admin', '2024-07-24 15:05:18', '1');
INSERT INTO `sys_counts_task_item` VALUES ('778459647fd69727e92ce34740253f0f', '1', 'DS_INDEX_SHZRF_COUNTS_TASK', '族占比', 'datas', '0', '1', null, 'SELECT r.scrutinydate name,count(1) `value` from scientific_names_info r WHERE !ISNULL(r.scrutinydate) AND r.scrutinydate!=\'\' GROUP BY r.scrutinydate LIMIT 20', null, null, null, 'admin', '2024-07-24 20:45:44', 'admin', '2024-07-24 15:05:18', '1');
INSERT INTO `sys_counts_task_item` VALUES ('8754lop47fd69727e92ce34740253f0f', '1', 'DS_INDEX_HY_COUNTS_TASK', '物种人数', 'datas', '0', '1', null, 'SELECT men `name`,count(1) value from `scientific_names_info` where !ISNULL(men) GROUP BY men ORDER BY value DESC limit 10', null, null, null, 'admin', '2024-07-24 20:45:44', 'admin', '2024-07-24 15:05:18', '1');
INSERT INTO `sys_counts_task_item` VALUES ('8899plok7fd69727e92ce34740253f0f', '1', 'DS_INDEX_DTFB_COUNTS_TASK', '地图分布', 'datas', '0', '1', null, 'SELECT d.name `name`,count(1) gdzr \r\nfrom dq d LEFT JOIN `scientific_names_info` s ON LOCATE(d.name,s.distributionc)>0 WHERE !ISNULL(s.distributionc) AND s.distributionc!=\'\' AND s.distributionc!=\'无\' GROUP BY d.name', null, null, null, 'admin', '2024-07-24 20:45:44', 'admin', '2024-07-24 15:05:18', '1');
INSERT INTO `sys_counts_task_item` VALUES ('jjkkml347fd69727e92ce34740253f0f', '1', 'DS_INDEX_ZRDJ_COUNTS_TASK', '物种门占比', 'datas', '0', '1', null, 'SELECT men `name`,count(1) value from `scientific_names_info` WHERE !ISNULL(men) AND men !=\'\' GROUP BY men ORDER BY value DESC LIMIT 25', null, null, null, 'admin', '2024-07-24 20:45:44', 'admin', '2024-07-24 15:05:18', '1');
INSERT INTO `sys_counts_task_item` VALUES ('oplm12347fd69727e92ce34740253f0f', '1', 'DS_INDEX_QYZR_COUNTS_TASK', '纲人数', 'datas', '0', '1', null, 'SELECT gang `name`,count(1) value from `scientific_names_info` WHERE !ISNULL(gang) AND gang !=\'\' GROUP BY name ORDER BY value DESC LIMIT 10', null, null, null, 'admin', '2024-07-24 20:45:44', 'admin', '2024-07-24 15:05:18', '1');
INSERT INTO `sys_counts_task_item` VALUES ('qwer23447fd69727e92ce34740253f0f', '1', 'DS_INDEX_ZGBFB_COUNTS_TASK', '类占比', 'datas', '0', '1', null, 'SELECT mu `name`,count(1) value from `scientific_names_info` WHERE !ISNULL(mu) AND mu!=\'\' GROUP BY mu ORDER BY value desc limit 10', null, null, null, 'admin', '2024-07-24 20:45:44', 'admin', '2024-07-24 15:05:18', '1');
