-- ----------------------------
-- Table structure for sys_config
-- ----------------------------
DROP TABLE IF EXISTS `sys_config`;
CREATE TABLE `sys_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `param_key` varchar(50) DEFAULT NULL COMMENT 'key',
  `param_value` varchar(2000) DEFAULT NULL COMMENT 'value',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态   0：隐藏   1：显示',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `param_key` (`param_key`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='系统配置信息表';

-- ----------------------------
-- Records of sys_config
-- ----------------------------

-- ----------------------------
-- Table structure for sys_counts_task
-- ----------------------------
DROP TABLE IF EXISTS `sys_counts_task`;
CREATE TABLE `sys_counts_task` (
  `id` varchar(32) NOT NULL,
  `case_id` int(11) DEFAULT NULL COMMENT '应用ID',
  `name` varchar(100) DEFAULT NULL COMMENT '任务名称',
  `task_code` varchar(100) DEFAULT NULL COMMENT '任务编码',
  `cache` int(11) DEFAULT '0' COMMENT '是否缓存 0 否 1 是',
  `cache_key` varchar(255) DEFAULT NULL COMMENT '缓存KEY',
  `cache_time` varchar(255) DEFAULT NULL COMMENT '缓存失效',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `start` int(11) DEFAULT '1' COMMENT '是否开启 0 否 1 是',
  `del_flag` int(11) DEFAULT '1' COMMENT '删除状态 0 无效 1 有效',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `task_code` (`case_id`,`task_code`) USING BTREE,
  UNIQUE KEY `cache_key` (`cache_key`,`case_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of sys_counts_task
-- ----------------------------

-- ----------------------------
-- Table structure for sys_counts_task_item
-- ----------------------------
DROP TABLE IF EXISTS `sys_counts_task_item`;
CREATE TABLE `sys_counts_task_item` (
  `id` varchar(32) NOT NULL,
  `case_id` int(11) DEFAULT NULL,
  `task_code` varchar(100) DEFAULT NULL COMMENT '统计任务编码',
  `name` varchar(255) DEFAULT NULL COMMENT '统计项名称',
  `res` varchar(100) DEFAULT NULL COMMENT '返回值KEY',
  `type` int(11) DEFAULT '0' COMMENT '统计项类型 0 SQL 1 文本 ',
  `back` int(11) DEFAULT '1' COMMENT '是否返回 0 否 1 是',
  `before_func` varchar(500) DEFAULT NULL COMMENT '前置处理函数',
  `item_text` text COMMENT '统计项内容',
  `after_func` varchar(255) DEFAULT NULL COMMENT '后置处理函数',
  `test_param` varchar(500) DEFAULT NULL COMMENT '接口测试参数',
  `init_param` text COMMENT '初始化预加载参数',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` int(11) DEFAULT NULL COMMENT '删除状态 0 无效 1 有效',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `task_code` (`task_code`,`res`,`case_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of sys_counts_task_item
-- ----------------------------

-- ----------------------------
-- Table structure for sys_data_case
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_case`;
CREATE TABLE `sys_data_case` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `uid` varchar(50) DEFAULT NULL COMMENT '用户id',
  `sid` int(11) DEFAULT NULL COMMENT '关系存储数据源ID ',
  `name` varchar(500) DEFAULT NULL COMMENT '应用名称',
  `case_code` varchar(100) DEFAULT NULL COMMENT '标识',
  `ctype` varchar(50) DEFAULT NULL COMMENT '类型 ZJK 中间库 FXK 分析库',
  `del_flag` varchar(6) DEFAULT NULL COMMENT '是否删除 0 删除 1 未删除',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of sys_data_case
-- ----------------------------

-- ----------------------------
-- Table structure for sys_data_source
-- ----------------------------
DROP TABLE IF EXISTS `sys_data_source`;
CREATE TABLE `sys_data_source` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `url` varchar(192) DEFAULT NULL COMMENT 'ip地址',
  `port` varchar(10) DEFAULT NULL COMMENT '端口',
  `uname` varchar(50) DEFAULT NULL COMMENT '用户名',
  `pass` varchar(50) DEFAULT NULL COMMENT '密码',
  `dtype` varchar(50) DEFAULT NULL COMMENT '数据源类型 MYSQL CKHOUSE ',
  `ctype` varchar(50) DEFAULT NULL,
  `slavp` varchar(500) DEFAULT NULL COMMENT '从机器ip，多个以 , 隔开',
  `del_flag` int(11) DEFAULT NULL COMMENT '是否删除 0 删除 1 未删除',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of sys_data_source
-- ----------------------------

-- ----------------------------
-- Table structure for sys_dept
-- ----------------------------
DROP TABLE IF EXISTS `sys_dept`;
CREATE TABLE `sys_dept` (
  `dept_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `parent_id` bigint(20) DEFAULT NULL COMMENT '上级部门ID，一级部门为0',
  `name` varchar(50) DEFAULT NULL COMMENT '部门名称',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  `del_flag` tinyint(4) DEFAULT '0' COMMENT '是否删除  -1：已删除  0：正常',
  PRIMARY KEY (`dept_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='部门管理';

-- ----------------------------
-- Records of sys_dept
-- ----------------------------

-- ----------------------------
-- Table structure for sys_dict
-- ----------------------------
DROP TABLE IF EXISTS `sys_dict`;
CREATE TABLE `sys_dict` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '字典名称',
  `type` varchar(100) NOT NULL COMMENT '字典类型',
  `code` varchar(100) NOT NULL COMMENT '字典码',
  `value` varchar(1000) NOT NULL COMMENT '字典值',
  `order_num` int(11) DEFAULT '0' COMMENT '排序',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `del_flag` tinyint(4) DEFAULT '0' COMMENT '删除标记  -1：已删除  0：正常',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `type` (`type`,`code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='数据字典表';

-- ----------------------------
-- Records of sys_dict
-- ----------------------------

-- ----------------------------
-- Table structure for sys_log
-- ----------------------------
DROP TABLE IF EXISTS `sys_log`;
CREATE TABLE `sys_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) DEFAULT NULL COMMENT '用户名',
  `operation` varchar(50) DEFAULT NULL COMMENT '用户操作',
  `method` varchar(200) DEFAULT NULL COMMENT '请求方法',
  `params` varchar(5000) DEFAULT NULL COMMENT '请求参数',
  `time` bigint(20) NOT NULL COMMENT '执行时长(毫秒)',
  `ip` varchar(64) DEFAULT NULL COMMENT 'IP地址',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=363 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='系统日志';

-- ----------------------------
-- Records of sys_log
-- ----------------------------

-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS `sys_menu`;
CREATE TABLE `sys_menu` (
  `menu_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `parent_id` bigint(20) DEFAULT NULL COMMENT '父菜单ID，一级菜单为0',
  `name` varchar(50) DEFAULT NULL COMMENT '菜单名称',
  `url` varchar(200) DEFAULT NULL COMMENT '菜单URL',
  `perms` varchar(500) DEFAULT NULL COMMENT '授权(多个用逗号分隔，如：user:list,user:create)',
  `type` int(11) DEFAULT NULL COMMENT '类型   0：目录   1：菜单   2：按钮',
  `icon` varchar(50) DEFAULT NULL COMMENT '菜单图标',
  `order_num` int(11) DEFAULT NULL COMMENT '排序',
  PRIMARY KEY (`menu_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='菜单管理';

-- ----------------------------
-- Records of sys_menu
-- ----------------------------

